<script>
import {data,profile,updateData,notify} from '../lib/store.js';
import {PROFILE_PAGES,PRIVACY_FIELDS,SHARE_SCOPES,ADDRESS_TYPES,ACCOUNT_LINKS,saveContact,normalizePreferred,addressError,emergencyError,delegateError} from '../lib/student-account.js';
import Modal from '../lib/components/Modal.svelte';import Icon from '../lib/components/Icon.svelte';
let {route}=$props();let view=$derived(route.split('/')[1]??'personal');let page=$derived(PROFILE_PAGES.find(p=>p.id===view));let tab=$state('Personal');
let preferred=$state($data.person.preferredName);let diploma=$state($data.person.diplomaName);let privacy=$state({...$data.person.privacy});let privacyDirty=$derived(PRIVACY_FIELDS.some(k=>privacy[k]!==$data.person.privacy[k]));
let editor=$state(null);let row=$state({});let error=$state('');let removal=$state(null);
function savePerson(person,message){updateData({...$data,person});notify(message);}
function preference(key,value){updateData({...$data,preferences:{...$data.preferences,[key]:value}});notify('Preference saved for this profile.');}
function edit(kind,existing={},type=''){error='';editor=kind;row={id:'',name:'',value:'',type:type||(kind==='emails'?'Home':'Cell'),preferred:false,street:'',line2:'',city:'',region:'',postal:'',country:'United States',from:'2026-11-15',relationship:'',phone:'',email:'',scopes:[],...existing,scopes:[...(existing.scopes??[])]};}
function save(e){e.preventDefault();const person=$data.person;
 if(['emails','phones'].includes(editor)){const result=saveContact(person,editor,row);if(result.error){error=result.error;return;}savePerson(result.person,'Contact saved in this browser.');}
 else {error=editor==='addresses'?addressError(row):editor==='emergency'?emergencyError(row):delegateError(row);if(error)return;const id=row.id||`${editor}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;let entries=person[editor].filter(r=>r.id!==id&&(editor!=='addresses'||r.type!==row.type));let record;
 if(editor==='addresses')record={id,type:row.type,street:row.street.trim(),line2:row.line2.trim(),city:row.city.trim(),region:row.region.trim(),postal:row.postal.trim(),country:row.country.trim(),from:row.from};
 else if(editor==='emergency'){const preferred=row.preferred||!entries.length;entries=entries.map(r=>({...r,preferred:preferred?false:r.preferred}));record={id,name:row.name.trim(),relationship:row.relationship.trim(),phone:row.phone.trim(),preferred};}
 else record={id,name:row.name.trim(),email:row.email.trim(),scopes:SHARE_SCOPES.filter(s=>row.scopes.includes(s)),status:'Draft'};
 entries.push(record);if(editor==='emergency')entries=normalizePreferred(entries);savePerson({...person,[editor]:entries},editor==='delegates'?'Sharing draft saved. No access or invitation was sent.':'information saved in this browser.');}
 editor=null;
}
function remove(){const {kind,id}=removal;let entries=$data.person[kind].filter(r=>r.id!==id);if(['emails','phones','emergency'].includes(kind))entries=normalizePreferred(entries);savePerson({...$data.person,[kind]:entries},kind==='delegates'?'Sharing draft removed.':'entry removed.');removal=null;}
function saveNames(e){e.preventDefault();if(!preferred.trim()||!diploma.trim())return;savePerson({...$data.person,preferredName:preferred.trim(),diplomaName:diploma.trim()},'Display names saved for this profile.');}
function scopeChange(scope,checked){row={...row,scopes:checked?[...row.scopes,scope]:row.scopes.filter(s=>s!==scope)};}
</script>
{#if page}<nav class="academic-breadcrumb" aria-label="Profile breadcrumb"><a href="#/profile">My Profile</a><Icon name="chevron" size={12}/><span>{page.label}</span></nav>
<div class="page-heading"><div><p class="eyebrow">Your details, in your control</p><h1>My Profile</h1><p>{page.label}</p></div><span class="badge neutral">Student record</span></div>
<div class="panel profile-identity"><div class="avatar large">{$data.person.preferredName.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><div><h2>{$data.person.preferredName}</h2><p>{$profile.studentId} · {$profile.year}</p><span class="muted small">{$profile.major} · {$profile.degree}</span></div></div>
<nav class="profile-section-tabs" aria-label="Profile sections">{#each PROFILE_PAGES as item}<a href={item.href} aria-current={item.id===view?'page':undefined}><Icon name={item.icon} size={16}/>{item.label}</a>{/each}</nav>
{#if view==='personal'}<section class="panel padded academic-copy"><div class="section-heading"><h2>Personal Details</h2></div><div class="category-chips spaced" aria-label="Personal details views">{#each ['Personal','Biographic','Preferences'] as item}<button aria-pressed={tab===item} class:active={tab===item} onclick={()=>tab=item}>{item}</button>{/each}</div>
{#if tab==='Personal'}<details class="account-disclosure" open><summary>Names</summary><dl class="academic-definition"><div><dt>Primary</dt><dd>{$profile.name}</dd></div><div><dt>Preferred</dt><dd>{$data.person.preferredName}</dd></div><div><dt>Diploma</dt><dd>{$data.person.diplomaName}</dd></div></dl><form class="academic-form" onsubmit={saveNames}><div class="form-two-columns"><label>Preferred name<input required maxlength="120" bind:value={preferred}/></label><label>Diploma name<input required maxlength="120" bind:value={diploma}/></label></div><button class="button primary">Save names</button></form><p class="fine-print">Preferred name updates this workspace’s greeting. Use the university’s record update process to change your diploma name.</p></details>
{#each ['Citizenship','Current Residency','Visa Status'] as field}<details class="account-disclosure"><summary>{field}</summary><p class="muted">Not recorded. Review or update official records through the university.</p><a class="text-link" href={ACCOUNT_LINKS.help} target="_blank" rel="noreferrer">Official personal information help<Icon name="external" size={15}/></a></details>{/each}
{:else if tab==='Biographic'}<h3>Biographic information</h3><dl class="academic-definition"><div><dt>Date of birth</dt><dd>Not recorded</dd></div><div><dt>Student record</dt><dd>{$profile.studentId}</dd></div><div><dt>Academic level</dt><dd>{$profile.year}</dd></div><div><dt>College</dt><dd>{$profile.college}</dd></div><div><dt>Target graduation</dt><dd>{$profile.graduation}</dd></div></dl><p class="fine-print">Use official university services for corrections to protected identity information.</p>
{:else}<h3>Workspace preferences</h3><label class="task-check"><input type="checkbox" checked={$data.preferences.reminders} onchange={e=>preference('reminders',e.currentTarget.checked)}/><span><strong>Show task reminders</strong><small>Display the remaining task count in navigation.</small></span></label><label class="task-check"><input type="checkbox" checked={$data.preferences.compactSchedule} onchange={e=>preference('compactSchedule',e.currentTarget.checked)}/><span><strong>Compact schedule display</strong><small>Reduce spacing in your weekly schedule.</small></span></label>{/if}</section>
{:else if view==='contact'}<section class="panel padded academic-copy"><h2>Contact Details</h2><p>Add, edit, and choose your preferred contact details.</p>{#each ['emails','phones'] as kind}<div class="section-heading spaced"><h3>{kind==='emails'?'Email':'Phone'}</h3><button class="button secondary" onclick={()=>edit(kind)}>Add {kind==='emails'?'email':'phone'}<Icon name="plus" size={15}/></button></div>{#if $data.person[kind].length}<div class="account-records">{#each $data.person[kind] as contact}<article class="account-record"><div><strong>{contact.value}</strong><small>{contact.type} {contact.preferred?'· Preferred':''}</small></div>{#if contact.id==='campus'}<span class="badge neutral">Campus email</span>{:else}<div class="button-row"><button class="button quiet" aria-label={`Edit ${contact.value}`} onclick={()=>edit(kind,contact)}>Edit</button><button class="button quiet" aria-label={`Remove ${contact.value}`} onclick={()=>removal={kind,id:contact.id}}>Remove</button></div>{/if}</article>{/each}</div>{:else}<div class="account-empty"><Icon name="phone"/><p>No phone numbers defined.</p></div>{/if}{/each}</section>
{:else if view==='addresses'}<section class="panel padded academic-copy"><h2>Addresses</h2><p>Manage your permanent, mailing, and diploma addresses.</p>{#each ADDRESS_TYPES as type}{@const address=$data.person.addresses.find(a=>a.type===type)}<div class="section-heading spaced"><h3>{type}</h3><button class="button secondary" onclick={()=>edit('addresses',address??{},type)}>{address?'Edit':'Add'} address<Icon name={address?'chevron':'plus'} size={15}/></button></div>{#if address}<article class="account-record"><div><strong>{address.street}</strong>{#if address.line2}<small>{address.line2}</small>{/if}<small>{address.city}{address.region?', '+address.region:''} {address.postal}</small><small>{address.country} · From {address.from}</small></div><button class="button quiet" aria-label={`Remove ${type}`} onclick={()=>removal={kind:'addresses',id:address.id}}>Remove</button></article>{:else}<p class="account-empty">No address defined.</p>{/if}{/each}</section>
{:else if view==='emergency'}<section class="panel padded academic-copy"><div class="section-heading"><h2>Emergency Contacts</h2><button class="button primary" onclick={()=>edit('emergency')}>Add Contact<Icon name="plus" size={15}/></button></div>{#if !$data.person.emergency.length}<div class="empty-state"><Icon name="people" size={32}/><h3>No contacts defined.</h3><p>Add the person you want contacted in an emergency.</p></div>{:else}<div class="account-records spaced">{#each $data.person.emergency as contact}<article class="account-record"><div><strong>{contact.name}</strong><small>{contact.relationship} · {contact.phone}</small>{#if contact.preferred}<span class="badge success">Primary contact</span>{/if}</div><div class="button-row"><button class="button secondary" aria-label={`Edit ${contact.name}`} onclick={()=>edit('emergency',contact)}>Edit</button><button class="button quiet" aria-label={`Remove ${contact.name}`} onclick={()=>removal={kind:'emergency',id:contact.id}}>Remove</button></div></article>{/each}</div>{/if}<p class="fine-print">contacts stay in this browser. No emergency service or university contact record is connected.</p></section>
{:else if view==='privacy'}<section class="panel padded academic-copy"><div class="section-heading"><h2>Privacy Restrictions</h2><button class="button primary" disabled={!privacyDirty} onclick={()=>savePerson({...$data.person,privacy:{...privacy}},'Privacy draft saved locally. Official restrictions are unchanged.')}>Save privacy draft</button></div><p>Explore restrictions by information category. These controls save a local draft; they do not change your official FERPA settings.</p>{#each PRIVACY_FIELDS as field}<details class="account-disclosure"><summary>{field}<span class="badge neutral">{privacy[field]?'Restrict in draft':'No draft restriction'}</span></summary><label class="task-check"><input type="checkbox" checked={privacy[field]} onchange={e=>privacy={...privacy,[field]:e.currentTarget.checked}}/><span><strong>Restrict {field.toLowerCase()} in this draft</strong><small>Review official university guidance before changing your actual record.</small></span></label></details>{/each}<a class="text-link spaced" href={ACCOUNT_LINKS.help} target="_blank" rel="noreferrer">Official personal information & delegated access help<Icon name="external" size={15}/></a></section>
{:else if view==='sharing'}<section class="panel padded academic-copy"><div class="section-heading"><h2>Share My Information – Summary</h2><button class="button primary" onclick={()=>edit('delegates')}>Delegate Access to a New Contact<Icon name="plus" size={15}/></button></div><p>Choose access areas for a trusted contact. Drafts are stored here for review. No invitation, login, or access grant is created.</p>{#if !$data.person.delegates.length}<div class="account-empty"><Icon name="shield"/><p>No current delegated access drafts found.</p></div>{:else}<div class="account-records">{#each $data.person.delegates as delegate}<article class="account-record"><div><strong>{delegate.name}</strong><small>{delegate.email}</small><small>{delegate.scopes.join(' · ')}</small><span class="badge warning">Draft · no access granted</span></div><div class="button-row"><button class="button secondary" aria-label={`Edit sharing draft for ${delegate.name}`} onclick={()=>edit('delegates',delegate)}>Edit</button><button class="button quiet" aria-label={`Remove sharing draft for ${delegate.name}`} onclick={()=>removal={kind:'delegates',id:delegate.id}}>Remove draft</button></div></article>{/each}</div>{/if}<a class="text-link spaced" href={ACCOUNT_LINKS.help} target="_blank" rel="noreferrer">Set up actual delegated access through UC<Icon name="external" size={15}/></a></section>{/if}
<p class="fine-print">Changes are saved in this browser and remain separate for each student.</p>
{:else}<section class="empty-state panel"><h1>Profile section not found.</h1><a class="button primary" href="#/profile">My Profile</a></section>{/if}
{#if editor}<Modal title={editor==='delegates'?'Sharing draft':editor==='addresses'?'address':editor==='emergency'?'Emergency contact':editor==='emails'?'Email address':'Phone number'} onclose={()=>editor=null}><p class="fine-print">Saved changes stay in this browser.</p><form class="academic-form" onsubmit={save}>
{#if ['emails','phones'].includes(editor)}<label>{editor==='emails'?'Email':'Phone'}<input data-initial-focus required type={editor==='emails'?'email':'tel'} maxlength="200" placeholder={editor==='emails'?'student@example.com':'+1 202 555 0147'} bind:value={row.value}/></label><label>Type<select bind:value={row.type}>{#each editor==='emails'?['Home','Other']:['Cell','Home','Emergency Text','Other'] as type}<option>{type}</option>{/each}</select></label><label class="checkbox-label"><input type="checkbox" bind:checked={row.preferred}/>Preferred {editor==='emails'?'email':'phone'}</label>
{:else if editor==='addresses'}<label>Address type<select bind:value={row.type}>{#each ADDRESS_TYPES as type}<option>{type}</option>{/each}</select></label><label>Street address<input data-initial-focus required maxlength="120" placeholder="Street address" bind:value={row.street}/></label><label>Apartment / line 2<input maxlength="120" bind:value={row.line2}/></label><div class="form-two-columns"><label>City<input required maxlength="120" placeholder="City" bind:value={row.city}/></label><label>State / region<input maxlength="120" bind:value={row.region}/></label></div><div class="form-two-columns"><label>Postal code<input required maxlength="30" placeholder="00000" bind:value={row.postal}/></label><label>Country<input required maxlength="120" bind:value={row.country}/></label></div><label>Effective from<input type="date" required bind:value={row.from}/></label>
{:else}<label>Contact name<input data-initial-focus required maxlength="120" placeholder="Contact name" bind:value={row.name}/></label>{#if editor==='emergency'}<label>Relationship<input required maxlength="120" placeholder="Friend" bind:value={row.relationship}/></label><label>Phone<input type="tel" required maxlength="40" placeholder="+1 202 555 0147" bind:value={row.phone}/></label><label class="checkbox-label"><input type="checkbox" bind:checked={row.preferred}/>Primary emergency contact</label>{:else}<label>Contact email<input type="email" required maxlength="200" placeholder="jamie@example.com" bind:value={row.email}/></label><fieldset class="account-scopes"><legend>Access areas to include in draft</legend>{#each SHARE_SCOPES as scope}<label class="checkbox-label"><input type="checkbox" checked={row.scopes.includes(scope)} onchange={e=>scopeChange(scope,e.currentTarget.checked)}/>{scope}</label>{/each}</fieldset>{/if}{/if}
{#if error}<p class="form-error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button secondary" type="button" onclick={()=>editor=null}>Cancel</button><button class="button primary" type="submit">{editor==='delegates'?'Save sharing draft':'Save entry'}</button></div></form></Modal>{/if}
{#if removal}<Modal title="Remove this entry?" onclose={()=>removal=null}><p class="modal-intro">This removes the saved {removal.kind==='delegates'?'sharing draft':'entry'} from this profile in this browser.</p><div class="modal-actions"><button class="button secondary" onclick={()=>removal=null}>Keep entry</button><button class="button primary" onclick={remove}>Remove entry</button></div></Modal>{/if}
